'use strict';
/**
 * Bundles Boostline's core for the head unit (core/index.ts -> app/boostline-core.js) and the
 * emulator's fake DME (emu/fakeDme.ts -> build/fake-dme.js).
 *
 *   node tools/bundle.js            once
 *   node tools/bundle.js --watch    again on every save (tools/emu.js runs this)
 *
 * The head-unit bundle targets Node 8 (the MGU runs its apps on it): esbuild lowers the syntax,
 * core/polyfills.ts adds the few library calls Node 8 lacks, and test:node8 runs it on a real Node 8.
 * enet.ts's './hsfz' resolves to core/hsfzOverTasu.ts (UDS over the head unit's transport).
 */
const path = require('path');
const esbuild = require('esbuild');

const ROOT = path.resolve(__dirname, '..');
const BOOSTLINE = path.join(ROOT, 'vendor', 'boostline');

/** Boostline's path aliases (tsconfig.node.json), node: imports for Node 8, and the TASU seam. */
const boostlineResolve = {
    name: 'boostline-resolve',
    setup(build) {
        build.onResolve({ filter: /^@(shared|core)\// }, (a) => ({ path: resolveTs(path.join(BOOSTLINE, 'src', a.path.slice(1))) }));
        build.onResolve({ filter: /^@boostline\// }, (a) => ({ path: path.join(BOOSTLINE, a.path.slice('@boostline/'.length)) }));
        // Node 8 has no node: prefix
        build.onResolve({ filter: /^node:/ }, (a) => ({ path: a.path.slice(5), external: true }));
        build.onResolve({ filter: /^\.\/hsfz$/ }, (a) => {
            if (path.basename(a.importer) !== 'enet.ts') return undefined;
            return { path: path.join(ROOT, 'core', 'hsfzOverTasu.ts') };
        });
    },
};

function resolveTs(p) {
    const fs = require('fs');
    for (const ext of ['', '.ts', '.tsx', '/index.ts']) if (fs.existsSync(p + ext) && fs.statSync(p + ext).isFile()) return p + ext;
    return p;
}

const banner = '// GENERATED by tools/bundle.js from Boostline (vendor/boostline, MIT) and core/. Do not edit.\n';

const targets = [
    {
        entryPoints: [path.join(ROOT, 'core', 'index.ts')],
        outfile: path.join(ROOT, 'app', 'boostline-core.js'),
        target: 'node8',
        banner: { js: banner + "'use strict';" },
    },
    {
        entryPoints: [path.join(ROOT, 'emu', 'fakeDme.ts')],
        outfile: path.join(ROOT, 'build', 'fake-dme.js'),
        target: 'node8',            // (test:node8 runs it beside the app's bundle)
        banner: { js: '// GENERATED by tools/bundle.js from emu/fakeDme.ts. Do not edit.' },
        // hu-stub.js calls the module itself: require(file)(log)
        footer: { js: 'module.exports = Object.assign(module.exports.default, module.exports);' },
    },
];

async function main() {
    const watch = process.argv.includes('--watch');
    for (const t of targets) {
        const opts = Object.assign({
            bundle: true, platform: 'node', format: 'cjs', logLevel: 'warning', legalComments: 'inline',
            supported: { 'dynamic-import': false }, plugins: [boostlineResolve],
        }, t);
        if (watch) {
            const ctx = await esbuild.context(Object.assign({}, opts, {
                plugins: [boostlineResolve, { name: 'report', setup(b) { b.onEnd((r) => { if (!r.errors.length) console.log('bundle: ' + path.relative(ROOT, t.outfile)); }); } }],
            }));
            await ctx.watch();
        } else {
            await esbuild.build(opts);
            console.log('bundle: ' + path.relative(ROOT, t.outfile));
        }
    }
}

main().catch((e) => { console.error(e.message || e); process.exit(1); });
